            typ = parts[1]
            name = parts[2]
            # Include only code symbols (skip \$d data markers)
            if not name.startswith('\$d') and not name.startswith('\$x'):
                symbols.append((addr, typ, name))
        except ValueError:
            pass

sym_addrs = [s[0] for s in symbols]

