import subprocess, bisect

# Get all FUNC symbols and sort them, find what's around 0x2f4b20
result = subprocess.run(['readelf', '-W', '-s', 'libmonosgen-2.0.so.debug'], capture_output=True, text=True)
symbols = []
for line in result.stdout.splitlines():
    parts = line.split()
    if len(parts) >= 8 and parts[3] == 'FUNC':
        try:
            addr = int(parts[1], 16)
            size = int(parts[2])
            name = parts[7]
            if addr > 0:
                symbols.append((addr, size, name))
        except (ValueError, IndexError):
            pass

symbols.sort()

# Find functions that contain or are near 0x2f4b20 and 0x2f4c84
for target in [0x2f4b20, 0x2f4c84]:
    print(f"\nLooking for 0x{target:x}:")
    for addr, size, name in symbols:
        if addr <= target < addr + size:
            print(f"  CONTAINS: {name} @ 0x{addr:x} size={size} offset=+0x{target-addr:x}")
        elif abs(addr - target) < 0x2000:
            print(f"  NEAR: {name} @ 0x{addr:x} size={size}")
EOF

